import React, { useState } from 'react';

const QuanLyThongBaoCuDan = () => {
    const [activeTab, setActiveTab] = useState('xem');

    return (
        <div style={styles.wrapper}>
            <header style={styles.header}>
                <h2 style={styles.mainTitle}>🔔 Trung Tâm Thông Báo & Kết Nối</h2>
                <div style={styles.tabBar}>
                    <button 
                        onClick={() => setActiveTab('xem')} 
                        style={{...styles.tabBtn, backgroundColor: activeTab === 'xem' ? '#2e7d32' : 'transparent', color: activeTab === 'xem' ? '#fff' : '#718096'}}
                    >
                        📢 Xem thông báo
                    </button>
                    <button 
                        onClick={() => setActiveTab('admin')} 
                        style={{...styles.tabBtn, backgroundColor: activeTab === 'admin' ? '#1976d2' : 'transparent', color: activeTab === 'admin' ? '#fff' : '#718096'}}
                    >
                        👨‍💼 Gửi Admin
                    </button>
                    <button 
                        onClick={() => setActiveTab('nhom')} 
                        style={{...styles.tabBtn, backgroundColor: activeTab === 'nhom' ? '#ed6c02' : 'transparent', color: activeTab === 'nhom' ? '#fff' : '#718096'}}
                    >
                        👥 Nhóm chung
                    </button>
                </div>
            </header>

            {/* Nội dung thay đổi theo Tab */}
            <div style={styles.contentArea}>
                {activeTab === 'xem' && (
                    <div className="fade-in">
                        <h3 style={{color: '#2e7d32', marginBottom: '20px', fontSize: '18px'}}>Thông báo từ Ban Quản Lý</h3>
                        <div style={styles.newsItem}>
                            <div style={styles.postHeader}>
                                <span style={styles.badgeMoi}>MỚI</span>
                                <span style={styles.timeLabel}>17/04/2026</span>
                            </div>
                            <h4 style={{margin: '10px 0', color: '#2d3748'}}>Thông báo bảo trì thang máy tòa A</h4>
                            <p style={styles.postContent}>Thang máy số 3 tòa A sẽ tạm dừng hoạt động để bảo trì định kỳ từ 14h-16h chiều nay. Mong cư dân thông cảm...</p>
                            <button style={styles.btnDetail}>Xem chi tiết nội dung</button>
                        </div>
                    </div>
                )}

                {activeTab === 'admin' && (
                    <div className="fade-in">
                        <h3 style={{color: '#1976d2', marginBottom: '20px', fontSize: '18px'}}>Gửi yêu cầu hỗ trợ</h3>
                        <input type="text" placeholder="Chủ đề (Vd: Sửa bóng đèn, vệ sinh hành lang...)" style={{...styles.input, borderLeft: '4px solid #1976d2'}} />
                        <textarea placeholder="Mô tả chi tiết vấn đề bạn gặp phải..." style={styles.textarea} />
                        <button style={{...styles.submitBtn, backgroundColor: '#1976d2', boxShadow: '0 4px 12px rgba(25, 118, 210, 0.2)'}}>📩 Gửi tới Admin</button>
                    </div>
                )}

                {activeTab === 'nhom' && (
                    <div className="fade-in">
                        <h3 style={{color: '#ed6c02', marginBottom: '20px', fontSize: '18px'}}>Bảng tin cộng đồng</h3>
                        <textarea 
                            placeholder="Chia sẻ tin tức với hàng xóm (Vd: Tìm đồ lạc, rủ mua chung...)" 
                            style={{...styles.textarea, borderLeft: '4px solid #ed6c02'}}
                        />
                        <button style={{...styles.submitBtn, backgroundColor: '#ed6c02', boxShadow: '0 4px 12px rgba(237, 108, 2, 0.2)'}}>🚀 Đăng lên nhóm chung</button>
                    </div>
                )}
            </div>
        </div>
    );
};

const styles = {
    wrapper: { width: '100%' },
    header: { textAlign: 'center', marginBottom: '40px' },
    mainTitle: { fontSize: '24px', fontWeight: 'bold', color: '#1a202c', marginBottom: '20px' },
    tabBar: { display: 'inline-flex', gap: '5px', backgroundColor: '#edf2f7', padding: '5px', borderRadius: '12px' },
    tabBtn: { padding: '10px 20px', border: 'none', borderRadius: '8px', cursor: 'pointer', fontWeight: '600', transition: '0.3s', fontSize: '14px' },
    contentArea: { marginTop: '10px' },
    input: { width: '100%', padding: '15px', marginBottom: '15px', borderRadius: '10px', border: '1px solid #e2e8f0', backgroundColor: '#f8fafc', boxSizing: 'border-box', outline: 'none' },
    textarea: { width: '100%', padding: '15px', height: '140px', marginBottom: '20px', borderRadius: '10px', border: '1px solid #e2e8f0', backgroundColor: '#f8fafc', resize: 'none', boxSizing: 'border-box', outline: 'none' },
    submitBtn: { width: '100%', padding: '15px', color: '#fff', border: 'none', borderRadius: '10px', fontWeight: 'bold', fontSize: '16px', cursor: 'pointer', transition: '0.2s' },
    newsItem: { border: '1px solid #edf2f7', padding: '20px', borderRadius: '16px', marginBottom: '15px', backgroundColor: '#fff', borderLeft: '5px solid #2e7d32' },
    postHeader: { display: 'flex', justifyContent: 'space-between', alignItems: 'center' },
    badgeMoi: { backgroundColor: '#fed7d7', color: '#c53030', padding: '4px 10px', borderRadius: '6px', fontSize: '11px', fontWeight: 'bold' },
    timeLabel: { color: '#a0aec0', fontSize: '12px' },
    postContent: { color: '#4a5568', lineHeight: '1.6', fontSize: '14px' },
    btnDetail: { background: 'none', border: 'none', color: '#2e7d32', fontWeight: 'bold', cursor: 'pointer', marginTop: '12px', padding: 0, fontSize: '13px', textDecoration: 'underline' }
};

export default QuanLyThongBaoCuDan;
